// La anti-repetición (misma alerta en 10 min) la hace Enviar_Alerta consultando alertas_auditoria.
// (En N8N 2.x la memoria del flujo no se conserva entre ejecuciones de flujos publicados.)
function primeraVez() { return true; }

// H5: desvío del baseline de seguridad (pg_settings_baseline de M2)
const filas = $input.all().map(i => i.json).filter(r => r.name);
if (filas.length === 0) return [];
const clave = 'H5:' + filas.map(r => r.name + '=' + r.actual).sort().join('|');
if (!primeraVez(clave)) return [];
return [{ json: {
  codigo: 'H5',
  severidad: 'CRÍTICA',
  tipo: 'Desvío del baseline de seguridad',
  tabla: 'pg_settings_baseline',
  detalle: 'Parámetros fuera de baseline: ' + filas.map(r => `${r.name} = ${r.actual} (esperado: ${r.valor_esperado})`).join('; '),
  query: 'ALTER SYSTEM SET ...',
  usuario: 'N/A (revisar log de PostgreSQL)',
  accion: 'Restaurar el valor seguro: ALTER SYSTEM RESET <parámetro>; SELECT pg_reload_conf();'
}}];
